'use strict';
const $=s=>document.querySelector(s);
function selectProject(id){if(!S.projects.some(p=>p.id===id))return;S.drafts??={};if(S.selected!==id){resetDockContext();S.drafts[S.selected]={summary:S.cvSummary,included:[...S.included]};S.selected=id;S.snapIndex=0;const d=S.drafts[id];S.cvSummary=d?.summary||null;S.included=d?.included||[...new Set(assess(project()).filter(r=>r[3]==="full").map(r=>r[2]).filter(Boolean))];S.chat=[]}S.drawer=false}
function updateFields(){const f=$("#capture-form");if(f)S.fields={...(S.fields||captureDefaults()),...Object.fromEntries(new FormData(f))}}
function projectMenu(id){const p=S.projects.find(x=>x.id===id);if(!p)return;modal(p.company,`<p>${h(p.title)}</p><div class="menuitems">${btn(L("Erfahrungspassung","Experience fit"),"pick-fit","","pulse",id)}${btn(L("Bearbeiten","Edit"),"project-edit","","edit",id)}${btn(L("Notiz ergänzen","Add note"),"pick-note","","note",id)}${btn(p.archived?L("Wiederherstellen","Restore"):L("Archivieren","Archive"),"archive","","archive",id)}${btn(L("Löschen …","Delete …"),"confirm-delete","danger","trash",id)}</div>`)}
function refForm(id){const r=S.refs.find(x=>x.id===id)||{id:"",org:"",role:"",years:"",body:"",skills:""};modal(id?L("Referenz bearbeiten","Edit reference"):L("Referenz hinzufügen","Add reference"),`<form id="ref-form" data-id="${h(r.id)}" class="form">${inputs("org",L("Projekt / Unternehmen","Project / company"),r.org,false,"text",true)}${inputs("role",L("Rolle","Role"),r.role)}${inputs("years",L("Zeitraum","Dates"),r.years)}${inputs("body",L("Dein persönlicher Beitrag","Your contribution"),T(r.body),true)}${inputs("skills",L("Technologien","Technologies"),r.skills)}<button class="btn primary">${L("Speichern","Save")}</button></form>`)}
async function suggestFields(){updateFields();const f=S.fields;const text=f.text?.trim();
if(!text){if(f.url?.includes("aster.example/")){fillExample();render();return}S.captureNeedsPaste=true;render();return}
S.captureNeedsPaste=false;
if(S.localModel){const b=document.querySelector('[data-act="suggest"]');if(b)b.disabled=true;try{const r=await fetch("./api/assma/extract",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({text,language:S.lang})});const d=await r.json();if(!r.ok||!d.fields)throw Error("model");for(const k of ["title","company","agency","contact","tech","required","preferred","terms"]){if(!f[k]&&typeof d.fields[k]==="string")f[k]=d.fields[k]}S.captureSuggested=true;render();return}catch{toast(L("Das lokale Modell ist gerade nicht erreichbar. Die Felder sind manuell editierbar.","The local model is unavailable. You can edit the fields manually."));if(b)b.disabled=false;return}}
if(text===T(brief)||text===brief[0]||text===brief[1]){fillExample()}else{const first=text.split(/[\n.!?]/)[0].slice(0,105).trim();f.title||=first;const tech=["Kotlin","Jetpack Compose","Android","iOS","Swift","Java","React","TypeScript","Spring","FHIR","TalkBack"].filter(v=>normal(text).includes(normal(v)));f.tech||=tech.join(", ");S.captureSuggested=true}render();toast(L("Vorschlag aus Beispieltext. Bitte alle Felder prüfen.","Suggestion from sample text. Review all fields."))}
function refObject(id){return S.refs.find(r=>r.id===id)}
async function exportFile(a){await seedReady;const p=project();if(!p)return;const s=["original","snap-md","snap-pdf"].includes(a)?selectedSnapshot(p.id):snapshotData(p,"","");if(!s)return;let base=(s.name+"_"+s.project.company).replace(/[^a-zA-Z0-9_\-]/g,"-");if(a==="original"){if(s.fileBytes)blobDownload(s.fileBytes,"application/pdf",s.fileName);return}if(a.endsWith("md")){blobDownload(cvText(s),"text/markdown;charset=utf-8",base+(a==="snap-md"?"-snapshot":"")+".md");return}blobDownload(await cvBytes(s),"application/pdf",base+(a==="snap-pdf"?"-snapshot":"")+".pdf")}
function availableSnapshot(){return !!project()&&!!S.snapshots[project().id]}
async function clickAction(a,id,el){if(performDockAction(a)||setProgressPeriod(a,id))return;switch(a){
case"theme":S.theme=S.theme==="dark"?"light":"dark";try{localStorage.setItem("assma.theme",S.theme)}catch{}render();break;
case"drawer":S.drawer=!S.drawer;render();break;
case"scene":S.scene=Number(id);$("#example").innerHTML=demo();$("#example").querySelector(`[data-id="${S.scene}"]`)?.focus({preventScroll:true});break;
case"ask":{const prompt=contextPrompts().find(x=>x[1]===id);if(prompt){dock.draft="";await ask(prompt[0],id);}break}
case"privacy":modal(L("Datennutzung in der Vorschau","Data use in the preview"),`<p>${L("Die Vorschau verwendet fiktive Projekte. Deine Eingaben bleiben bis zum Neuladen in diesem Browser. Sprache, Farbschema, Chatansicht und Vorlesen werden als Einstellungen gespeichert.","The preview uses fictional projects. Your entries stay in this browser until you reload. Language, theme, chat view and read-aloud preferences are saved.")}</p><p>${L("Spracheingabe nutzt die Spracherkennung auf deinem Gerät oder dein lokales Whisper. Die Online-Demo zeigt vorbereitete Antworten. In der lokalen Edition kann assma Fragen und den aktuellen Projektkontext an dein eigenes Ollama-Modell auf diesem Rechner übergeben.","Voice input uses on-device recognition or your local Whisper. The online demo shows sample responses. In the local edition, assma can send your question and the current project context to your own Ollama model on this computer.")}</p>`);break;
case"close-modal":closeModal();break;
case"submission-open":selectProject(id);S.snapIndex=Number(el.dataset.version)||0;go("snapshot");break;
case"pick-record":case"pick-note":case"pick-fit":selectProject(id);closeModal();go(a==="pick-note"?"note":a==="pick-fit"?"fit":project().channel?"application":"fit");break;
case"filter":S.activeFilter=id;render();break;
case"menu":projectMenu(id);break;
case"archive":{const p=S.projects.find(x=>x.id===id);if(!p)break;p.archived=!p.archived;S.activeFilter="all";S.search="";closeModal();go(p.archived?"archived":"opportunities");break}
case"confirm-delete":{const p=S.projects.find(x=>x.id===id);modal(L("Projekt löschen?","Delete project?"),`<p>${h(p.title)} · ${h(p.company)}</p><p>${L("Damit entfernst du dieses Beispielprojekt und seinen Verlauf aus der aktuellen Sitzung.","This removes the sample project and its history from the current session.")}</p><div class="acts">${btn(L("Abbrechen","Cancel"),"close-modal")}${btn(L("Projekt löschen","Delete project"),"delete","danger","trash",id)}</div>`);break}
case"delete":S.projects=S.projects.filter(p=>p.id!==id);delete S.snapshots[id];delete S.notes[id];if(S.selected===id&&S.projects[0])selectProject(S.projects[0].id);closeModal();go("opportunities");break;
case"project-edit":{selectProject(id);S.fields={...captureDefaults(),...project(),editId:id};if(id==="aster"){S.fields.text||=T(brief);S.fields.required||="Kotlin, Compose, TalkBack";S.fields.preferred||="Release, FHIR R4"}S.captureSuggested=false;S.captureNeedsPaste=false;closeModal();go("manual");break}
case"example":fillExample();render();break;
case"suggest":await suggestFields();break;
case"ref-add":refForm(null);break;
case"ref-edit":refForm(id);break;
case"show-ref":{const r=refObject(id);if(r)modal(r.id+" · "+r.org,`<p><b>${h(r.role)}</b> · ${h(r.years)}</p><p>${h(T(r.body))}</p><p>${h(r.skills)}</p>${linkBtn(L("Zum Erfahrungsprofil","Open experience profile"),"experience")}`);break}
case"profile-edit":{const p=S.profile;modal(L("Persönliche Angaben","General profile"),`<form id="profile-form" class="form">${inputs("name","Name",p.name,false,"text",true)}${inputs("role",L("Rolle","Role"),p.role)}${inputs("email","E-Mail",p.email,false,"email")}${inputs("location",L("Ort","Location"),p.location)}${inputs("summary",L("Kurzprofil","Summary"),T(p.summary),true)}<button class="btn primary">${L("Speichern","Save")}</button></form>`);break}
case"ref-up":{let i=S.included.indexOf(id);if(i>0)[S.included[i-1],S.included[i]]=[S.included[i],S.included[i-1]];render();break}
case"original":case"snap-md":case"snap-pdf":case"download-md":case"download-pdf":await exportFile(a);break;
}}
document.addEventListener("click",e=>{const x=e.target.closest("[data-act],[data-pick]");if(!x){if(e.target.closest("dialog a[href^='#']"))closeModal();return}if(x.dataset.pick){selectProject(x.dataset.pick);if(location.hash===x.getAttribute("href"))render();return}e.preventDefault();clickAction(x.dataset.act,x.dataset.id,x).catch(()=>toast(L("Die Aktion konnte nicht abgeschlossen werden.","The action could not be completed.")))});
document.addEventListener("input",e=>{if(e.target.closest("#capture-form"))updateFields();if(e.target.id==="search"){S.search=e.target.value;$("#regrows").innerHTML=registerRows()}if(e.target.name==="cvsummary"){S.cvSummary=e.target.value;$("#cv-paper").innerHTML=paper(snapshotData(project(),"",""))}});
document.addEventListener("change",e=>{let el=e.target;if(el.name==="snapshotVersion"){S.snapIndex=Number(el.value);render();return}if(el.matches("[data-language]")){S.lang=el.value==="en"?"en":"de";S.chat=[];try{localStorage.setItem("assma.lang",S.lang)}catch{}render()}if(el.name==="cvref"){if(el.checked){if(!S.included.includes(el.value))S.included.push(el.value)}else S.included=S.included.filter(x=>x!==el.value);render()}if(el.name==="portalFile"){S.portalFile=el.value;$("#port-file-wrap").hidden=el.value!=="own";$("#port-file-wrap input").required=el.value==="own"}});
async function submitForm(f){const d=Object.fromEntries(new FormData(f));switch(f.id){
case"seed-form":{let raw=String(d.brief||"").trim();S.fields=captureDefaults();S.captureNeedsPaste=false;S.captureSuggested=false;if(/^https?:\/\//i.test(raw)){S.fields.url=raw}else if(raw){S.fields.text=raw}else{fillExample()}go("capture");break}
case"capture-form":{let old=S.fields?.editId,prior=S.projects.find(x=>x.id===old);let p={...captureDefaults(),...(prior||{}),...d,id:prior?.id||"p"+Date.now().toString(36),status:prior?.status||"captured",archived:prior?.archived||false,when:prior?.when||demoDay+"T12:00",due:prior?.due||""};p.score=getScore(assess(p));if(prior)S.projects[S.projects.indexOf(prior)]=p;else S.projects.unshift(p);selectProject(p.id);S.fields=null;S.captureSuggested=false;S.captureNeedsPaste=false;go("fit");break}
case"import-form":{const ids=new FormData(f).getAll("refs");S.imported=sampleRefs.map(r=>ids.includes(r.id));for(const r of sampleRefs.filter(s=>ids.includes(s.id))){if(!S.refs.some(x=>x.id===r.id))S.refs.push(structuredClone(r))}go("experience");toast(L("Ausgewählte Einträge im Profil bestätigt.","Selected entries confirmed in your profile."));break}
case"profile-form":S.profile={...S.profile,...d};closeModal();render();break;
case"ref-form":{const rr=refObject(f.dataset.id);if(rr)Object.assign(rr,d);else S.refs.push({...d,id:"E"+String(Math.max(0,...S.refs.map(r=>Number(r.id.slice(1))||0))+1).padStart(2,"0")});closeModal();render();break}
case"chat-form":{const msg=String(d.message||"").trim();if(msg){dock.draft="";dock.writing=false;await ask(msg,null)}break}
case"note-form":{const p=project();p.status=d.status;p.due=d.due;if(d.body?.trim())(S.notes[p.id]??=[]).push({date:demoDay+"T12:05",body:d.body.trim()});go("application");toast(L("Kontakt aktualisiert.","Contact updated."));break}
case"apply-form":{const button=f.querySelector("button[type=submit]");button.disabled=true;try{await seedReady;const p=project(),portal=S.view==="portal",when=portal?d.when:demoDay+"T10:24";const s=snapshotData(p,portal?"portal":"email",when);
if(!portal||d.portalFile==="sample"){s.fileBytes=await cvBytes(s);s.fileName=cvName(p)}else if(d.portalFile==="own"){const file=f.elements.actualfile.files[0];if(!file||file.size>12*1024*1024){toast(L("Bitte eine PDF bis 12 MB wählen.","Choose a PDF up to 12 MB."));return}s.fileBytes=new Uint8Array(await file.arrayBuffer());s.fileName=file.name}
s.recipient=portal?"":d.to;s.message=portal?"":d.message;s.subject=portal?"":d.subject;s.project.url=portal?d.url:p.url;s.project.status="sent";s.project.channel=s.channel;s.project.when=when;
S.archiveSnapshots??={};if(S.snapshots[p.id])(S.archiveSnapshots[p.id]??=[]).push(S.snapshots[p.id]);S.snapshots[p.id]=s;S.snapIndex=0;Object.assign(p,{status:"sent",channel:s.channel,when,due:d.due});(S.notes[p.id]??=[]).push({date:when,body:portal?L("Portalvorgang manuell vermerkt.","Portal application recorded manually."):L("Beispielversand mit ausgewähltem CV bestätigt.","Example delivery confirmed with the selected CV.")});go("snapshot")}finally{button.disabled=false}break}
}}
document.addEventListener("submit",e=>{if(!e.target.matches("form"))return;e.preventDefault();submitForm(e.target).catch(()=>toast(L("Bitte Eingaben prüfen und erneut versuchen.","Check your entries and try again.")))});
window.addEventListener("hashchange",()=>{closeModal();S.drawer=false;render();if(["capture","manual"].includes(S.view))S.captureNeedsPaste=false;window.scrollTo({top:0,behavior:"instant"})});
$("#skip").addEventListener("click",e=>{e.preventDefault();$("#main")?.focus()});
seedReady=seedSnapshots().then(()=>{if(["application","snapshot","progress"].includes(S.view))render()}).catch(()=>{});
render();detectLocal();

